CREATE VIEW 'energy_fx_asof' AS ( 
DECLARE OVERRIDABLE @asof := now()
                SELECT symbol, mid(bid, ask) AS usd, ts
                FROM energy_quotes
                WHERE symbol IN ('EURUSD', 'GBPUSD', 'EURGBP') AND ts <= @asof AND ts > dateadd('h', -1, @asof::timestamp)
                LATEST ON ts PARTITION BY symbol
);

